window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2c610aabef11d419"]={"versions": [{"id": "FIG-2c610aabef11d419", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm (Zustands- und Ablaufdiagramm über der Zeitachse) im Kontext der AUTOSAR Runtime Environment (RTE, Classic Platform). Es illustriert das zeitliche Verhalten und die Aktivierungssteuerung einer <code>RunnableEntity</code> unter Verwendung des Konfigurationsparameters <code>minimumStartInterval</code> (Debouncing bzw. Ratenbegrenzung von Aktivierungen zur Entlastung des Schedulers und Vermeidung von Task-Überlastungen).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Runnable Main States (<code>started</code>)</strong>: Obere Zeitspur; visualisiert die tatsächliche Ausführung der Runnable Entity (grau = aktiv in Ausführung / gestartet, weiß = idle / beendet bzw. nicht gestartet).</li>\n<li><strong>Runnable Activation States</strong>: Untere Zeitspur; visualisiert die anstehenden Aktivierungszustände der Runnable Entity:</li>\n<li><code>activated</code> (dunkelgrauer Balken): Aktivierung steht an und ist startbereit (keine Debounce-Sperre aktiv).</li>\n<li><code>debounce activation</code> (punktiert/kariert schraffierter Balken): Aktivierung ist durch ein Event eingetroffen, wird jedoch während des aktiven Mindeststartintervalls gepuffert bzw. zurückgehalten.</li>\n<li>Weißer Bereich: Keine Aktivierung anhängig.</li>\n<li><strong>RTE Event (Blitz-Symbol)</strong>: Eintreffen eines auslösenden RTE-Ereignisses (z. B. <code>DataReceivedEvent</code>, <code>OperationInvokedEvent</code>).</li>\n<li><strong>Debounce Time / <code>minimumStartInterval</code> (roter Doppelpfeil)</strong>: Konfigurierter zeitlicher Mindestabstand zwischen zwei aufeinanderfolgenden Starts der Runnable Entity.</li>\n<li><strong>Vertikale Linien</strong>: Scheduling- bzw. Dispatch-Zeitpunkte, an denen das Runnable gestartet wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialer Start</strong>: Ein erstes RTE-Event versetzt das Runnable in den Zustand <code>activated</code>. Ein weiteres Event erhöht ggf. den Aktivierungszähler. Zum Dispatch-Zeitpunkt (erste vertikale Linie) wechselt das Runnable in den Zustand <code>started</code>; synchron dazu beginnt das erste <code>minimumStartInterval</code> (roter Pfeil).</li>\n<li><strong>Start nach Intervallablauf</strong>: Nach Beendigung des Runnables und Ablauf des ersten Intervalls führen nachfolgende Events erneut direkt zum Zustand <code>activated</code>. Mit dem nächsten Dispatch (zweite vertikale Linie) startet das Runnable erneut, und ein weiteres Mindeststartintervall beginnt.</li>\n<li><strong>Event-Eingang während des Mindeststartintervalls</strong>: Treffen ein oder mehrere Events während des laufenden <code>minimumStartInterval</code> ein (unabhängig davon, ob das Runnable noch im Zustand <code>started</code> ist oder bereits beendet wurde), wechselt der Aktivierungszustand in <code>debounce activation</code>.</li>\n<li><strong>Zustandsübergang bei Intervallende</strong>: Sobald das <code>minimumStartInterval</code> abläuft, wechselt der Zustand automatisch von <code>debounce activation</code> zu <code>activated</code>. Liegt Scheduler-Bereitschaft vor, wird das Runnable unmittelbar erneut gestartet (<code>started</code>) und ein neues Mindeststartintervall initiiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Spezifikation</strong>: Das Mindeststartintervall (Metamodell-Attribut <code>RunnableEntity.minimumStartInterval</code>) wird deterministisch mit dem Beginn der Ausführung (<code>started</code>) gestartet, nicht mit dem Eintreffen des RTE-Events oder der Terminierung des Runnables.</li>\n<li><strong>RTE-Generator-Anforderung</strong>: Der RTE-Generator muss für entprellte Runnables Timer- oder Zählerstrukturen (z. B. über OS-Alarme oder RTE-interne Zähler) instanziieren, die nach Ablauf des Intervalls den Übergang von <code>debounce activation</code> nach <code>activated</code> auslösen.</li>\n<li><strong>Systemauslegung</strong>: Dient der Begrenzung der Ausführungslast und verhindert die Blockade oder das Verhungern niederpriorer Tasks (Starvation) bei hochfrequenten Event-Bursts.</li>\n</ul>"}, {"id": "FIG-97bfa095eb20e4a2", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm (Zustands- und Ablaufdiagramm über der Zeitachse) im Kontext der AUTOSAR Runtime Environment (RTE, Classic Platform). Es illustriert das zeitliche Verhalten und die Aktivierungssteuerung einer <code>RunnableEntity</code> unter Verwendung des Konfigurationsparameters <code>minimumStartInterval</code> (Debouncing bzw. Ratenbegrenzung von Aktivierungen zur Entlastung des Schedulers und Vermeidung von Task-Überlastungen).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Runnable Main States (<code>started</code>)</strong>: Obere Zeitspur; visualisiert die tatsächliche Ausführung der Runnable Entity (grau = aktiv in Ausführung / gestartet, weiß = idle / beendet bzw. nicht gestartet).</li>\n<li><strong>Runnable Activation States</strong>: Untere Zeitspur; visualisiert die anstehenden Aktivierungszustände der Runnable Entity:</li>\n<li><code>activated</code> (dunkelgrauer Balken): Aktivierung steht an und ist startbereit (keine Debounce-Sperre aktiv).</li>\n<li><code>debounce activation</code> (punktiert/kariert schraffierter Balken): Aktivierung ist durch ein Event eingetroffen, wird jedoch während des aktiven Mindeststartintervalls gepuffert bzw. zurückgehalten.</li>\n<li>Weißer Bereich: Keine Aktivierung anhängig.</li>\n<li><strong>RTE Event (Blitz-Symbol)</strong>: Eintreffen eines auslösenden RTE-Ereignisses (z. B. <code>DataReceivedEvent</code>, <code>OperationInvokedEvent</code>).</li>\n<li><strong>Debounce Time / <code>minimumStartInterval</code> (roter Doppelpfeil)</strong>: Konfigurierter zeitlicher Mindestabstand zwischen zwei aufeinanderfolgenden Starts der Runnable Entity.</li>\n<li><strong>Vertikale Linien</strong>: Scheduling- bzw. Dispatch-Zeitpunkte, an denen das Runnable gestartet wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialer Start</strong>: Ein erstes RTE-Event versetzt das Runnable in den Zustand <code>activated</code>. Ein weiteres Event erhöht ggf. den Aktivierungszähler. Zum Dispatch-Zeitpunkt (erste vertikale Linie) wechselt das Runnable in den Zustand <code>started</code>; synchron dazu beginnt das erste <code>minimumStartInterval</code> (roter Pfeil).</li>\n<li><strong>Start nach Intervallablauf</strong>: Nach Beendigung des Runnables und Ablauf des ersten Intervalls führen nachfolgende Events erneut direkt zum Zustand <code>activated</code>. Mit dem nächsten Dispatch (zweite vertikale Linie) startet das Runnable erneut, und ein weiteres Mindeststartintervall beginnt.</li>\n<li><strong>Event-Eingang während des Mindeststartintervalls</strong>: Treffen ein oder mehrere Events während des laufenden <code>minimumStartInterval</code> ein (unabhängig davon, ob das Runnable noch im Zustand <code>started</code> ist oder bereits beendet wurde), wechselt der Aktivierungszustand in <code>debounce activation</code>.</li>\n<li><strong>Zustandsübergang bei Intervallende</strong>: Sobald das <code>minimumStartInterval</code> abläuft, wechselt der Zustand automatisch von <code>debounce activation</code> zu <code>activated</code>. Liegt Scheduler-Bereitschaft vor, wird das Runnable unmittelbar erneut gestartet (<code>started</code>) und ein neues Mindeststartintervall initiiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Spezifikation</strong>: Das Mindeststartintervall (Metamodell-Attribut <code>RunnableEntity.minimumStartInterval</code>) wird deterministisch mit dem Beginn der Ausführung (<code>started</code>) gestartet, nicht mit dem Eintreffen des RTE-Events oder der Terminierung des Runnables.</li>\n<li><strong>RTE-Generator-Anforderung</strong>: Der RTE-Generator muss für entprellte Runnables Timer- oder Zählerstrukturen (z. B. über OS-Alarme oder RTE-interne Zähler) instanziieren, die nach Ablauf des Intervalls den Übergang von <code>debounce activation</code> nach <code>activated</code> auslösen.</li>\n<li><strong>Systemauslegung</strong>: Dient der Begrenzung der Ausführungslast und verhindert die Blockade oder das Verhungern niederpriorer Tasks (Starvation) bei hochfrequenten Event-Bursts.</li>\n</ul>"}], "trans": [{"from": "FIG-2c610aabef11d419", "to": "FIG-97bfa095eb20e4a2", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
